#[derive(Clone)]
struct TraceServiceImpl {
    state: Arc<IngestState>,
    sender: Arc<IngestSender>,
}

#[derive(Clone)]
struct MetricsServiceImpl {
    state: Arc<IngestState>,
    sender: Arc<IngestSender>,
}

#[derive(Clone)]
struct LogsServiceImpl {
    state: Arc<IngestState>,
    sender: Arc<IngestSender>,
}

#[tonic::async_trait]
impl TraceService for TraceServiceImpl {
    #[tracing::instrument(
        skip(self, req),
        fields(
            rpc.system = "grpc",
            rpc.service = "TraceService",
            rpc.method = "Export",
            span_count = tracing::field::Empty,
            traceparent = tracing::field::Empty,
        ),
    )]
    async fn export(
        &self,
        req: Request<ExportTraceServiceRequest>,
    ) -> Result<Response<ExportTraceServiceResponse>, Status> {
        if let Some(tp) = extract_traceparent(req.metadata()) {
            tracing::Span::current().record("traceparent", tracing::field::display(&tp));
        }
        let payload = req.into_inner();
        let span_count = {
            let _decode_span = tracing::debug_span!("parse.protobuf").entered();
            count_spans(&payload)
        };
        tracing::Span::current().record("span_count", span_count);
        if let Err(e) = validate_resource_spans(&payload.resource_spans) {
            return Err(reject_invariant(e));
        }
        if let Err(e) = self.sender.try_send(Batch::Spans(payload.resource_spans)) {
            return Err(reject_channel(e));
        }
        self.state.record_spans(span_count);
        Ok(Response::new(ExportTraceServiceResponse::default()))
    }
}

